#include <string.h>

int main(void) {
    char hostel[16] = "Kaveri";
    printf("strlen = %zu, sizeof = %zu\n", strlen(hostel), sizeof hostel);
    printf("byte after the last letter = %d\n", hostel[6]);
    char word[] = "chai";
    printf("sizeof word = %zu (4 letters + the terminator)\n", sizeof word);
