    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void) {
    char line[32];
    if (fgets(line, sizeof line, stdin) == NULL) return 1;
    line[strcspn(line, "\n")] = '\0';        /* fgets keeps the newline: drop it */
    char tag[8];
    snprintf(tag, sizeof tag, "%s", line);   /* never writes past tag[7] */
    printf("read \"%s\" (%zu chars)\n", line, strlen(line));
    printf("tag  \"%s\" (cut to fit %zu bytes)\n", tag, sizeof tag);
    return 0;
}

