#include <ctype.h>
#include <stdio.h>
#include <string.h>

static int count_vowels(const char *s) {
    int count = 0;
    for (; *s != '\0'; s++) {
        char c = (char)tolower((unsigned char)*s);
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') count++;
    }
    return count;
}

int main(void) {
    char line[256];
    if (fgets(line, sizeof line, stdin) == NULL) line[0] = '\0';
    line[strcspn(line, "\n")] = '\0';
    printf("%d\n", count_vowels(line));
    return 0;
}
